#include <stdint.h>
#include <string.h>
#include <pthread.h>
typedef unsigned __int128 u128;
typedef uint32_t v8 __attribute__((vector_size(32)));
#define ROTL(x,n) (((x)<<(n))|((x)>>(32-(n))))
#define QR(a,b,c,d) a+=b; d^=a; d=ROTL(d,16); c+=d; b^=c; b=ROTL(b,12); a+=b; d^=a; d=ROTL(d,8); c+=d; b^=c; b=ROTL(b,7);
static inline uint32_t ld32(const uint8_t*p){uint32_t v;memcpy(&v,p,4);return v;}
static inline uint64_t ld64(const uint8_t*p){uint64_t v;memcpy(&v,p,8);return v;}

static void block1(const uint32_t in[16], uint32_t out[16]){
  uint32_t x[16]; memcpy(x,in,64);
  for(int i=0;i<10;i++){QR(x[0],x[4],x[8],x[12]);QR(x[1],x[5],x[9],x[13]);QR(x[2],x[6],x[10],x[14]);QR(x[3],x[7],x[11],x[15]);
    QR(x[0],x[5],x[10],x[15]);QR(x[1],x[6],x[11],x[12]);QR(x[2],x[7],x[8],x[13]);QR(x[3],x[4],x[9],x[14]);}
  for(int i=0;i<16;i++) out[i]=x[i]+in[i];
}
/* encrypt nblk8 groups of 8 blocks (512 bytes) */
static void enc8(const uint32_t st[16], uint32_t ctr, const uint8_t*in, uint8_t*out, size_t ngroups){
  for(size_t g=0;g<ngroups;g++){
    v8 x[16], s[16];
    for(int i=0;i<16;i++){ v8 t={st[i],st[i],st[i],st[i],st[i],st[i],st[i],st[i]}; s[i]=t; }
    v8 c={0,1,2,3,4,5,6,7}; s[12]=s[12]*0+(ctr)+c;
    for(int i=0;i<16;i++) x[i]=s[i];
    for(int i=0;i<10;i++){QR(x[0],x[4],x[8],x[12]);QR(x[1],x[5],x[9],x[13]);QR(x[2],x[6],x[10],x[14]);QR(x[3],x[7],x[11],x[15]);
      QR(x[0],x[5],x[10],x[15]);QR(x[1],x[6],x[11],x[12]);QR(x[2],x[7],x[8],x[13]);QR(x[3],x[4],x[9],x[14]);}
    for(int i=0;i<16;i++) x[i]+=s[i];
    uint32_t ks[128] __attribute__((aligned(32)));
    for(int w=0;w<16;w++) for(int l=0;l<8;l++) ks[l*16+w]=x[w][l];
    const uint64_t*ip=(const uint64_t*)in; uint64_t*op=(uint64_t*)out; const uint64_t*kp=(const uint64_t*)ks;
    for(int i=0;i<64;i++){uint64_t a; memcpy(&a,in+8*i,8); a^=kp[i]; memcpy(out+8*i,&a,8);}
    (void)ip;(void)op;
    in+=512; out+=512; ctr+=8;
  }
}
static void enc_tail(const uint32_t st[16], uint32_t ctr, const uint8_t*in, uint8_t*out, size_t len){
  uint32_t s[16], ks[16]; memcpy(s,st,64);
  while(len){ s[12]=ctr++; block1(s,ks); size_t n=len<64?len:64; const uint8_t*k=(const uint8_t*)ks;
    for(size_t i=0;i<n;i++) out[i]=in[i]^k[i]; in+=n; out+=n; len-=n; }
}
static void chacha_xor(const uint32_t st[16], uint32_t ctr, const uint8_t*in, uint8_t*out, size_t len){
  size_t g=len/512; enc8(st,ctr,in,out,g); size_t d=g*512; enc_tail(st,ctr+(uint32_t)(g*8),in+d,out+d,len-d);
}
/* poly1305 44-bit limbs */
typedef struct { uint64_t h[3]; } fe;
#define M44 0xfffffffffffULL
#define M42 0x3ffffffffffULL
static inline void fe_mul(fe*o,const fe*a,const fe*b){
  uint64_t r0=b->h[0],r1=b->h[1],r2=b->h[2], s1=r1*20, s2=r2*20;
  uint64_t h0=a->h[0],h1=a->h[1],h2=a->h[2];
  u128 d0=(u128)h0*r0+(u128)h1*s2+(u128)h2*s1;
  u128 d1=(u128)h0*r1+(u128)h1*r0+(u128)h2*s2;
  u128 d2=(u128)h0*r2+(u128)h1*r1+(u128)h2*r0;
  uint64_t c;
  c=(uint64_t)(d0>>44); h0=(uint64_t)d0&M44; d1+=c;
  c=(uint64_t)(d1>>44); h1=(uint64_t)d1&M44; d2+=c;
  c=(uint64_t)(d2>>42); h2=(uint64_t)d2&M42; h0+=c*5;
  c=h0>>44; h0&=M44; h1+=c;
  o->h[0]=h0;o->h[1]=h1;o->h[2]=h2;
}
static inline void fe_add(fe*o,const fe*a){ o->h[0]+=a->h[0];o->h[1]+=a->h[1];o->h[2]+=a->h[2]; }
/* h = horner over nblocks full 16-byte blocks starting from h */
static void poly_blocks(fe*hh,const fe*r,const uint8_t*m,size_t nb){
  uint64_t r0=r->h[0],r1=r->h[1],r2=r->h[2], s1=r1*20, s2=r2*20;
  uint64_t h0=hh->h[0],h1=hh->h[1],h2=hh->h[2];
  const uint64_t hib=1ULL<<40;
  while(nb--){
    uint64_t t0=ld64(m),t1=ld64(m+8);
    h0+=t0&M44; h1+=((t0>>44)|(t1<<20))&M44; h2+=((t1>>24)&M42)|hib;
    u128 d0=(u128)h0*r0+(u128)h1*s2+(u128)h2*s1;
    u128 d1=(u128)h0*r1+(u128)h1*r0+(u128)h2*s2;
    u128 d2=(u128)h0*r2+(u128)h1*r1+(u128)h2*r0;
    uint64_t c;
    c=(uint64_t)(d0>>44); h0=(uint64_t)d0&M44; d1+=c;
    c=(uint64_t)(d1>>44); h1=(uint64_t)d1&M44; d2+=c;
    c=(uint64_t)(d2>>42); h2=(uint64_t)d2&M42; h0+=c*5;
    c=h0>>44; h0&=M44; h1+=c;
    m+=16;
  }
  hh->h[0]=h0;hh->h[1]=h1;hh->h[2]=h2;
}
static void poly_padded(fe*h,const fe*r,const uint8_t*m,size_t len){
  size_t nb=len/16; poly_blocks(h,r,m,nb);
  if(len%16){ uint8_t b[16]={0}; memcpy(b,m+nb*16,len%16); poly_blocks(h,r,b,1); }
}
static void fe_pow(fe*o,const fe*r,uint64_t e){
  fe res={{1,0,0}}, b=*r;
  while(e){ if(e&1) fe_mul(&res,&res,&b); fe_mul(&b,&b,&b); e>>=1; }
  *o=res;
}
typedef struct { const uint32_t*st; const fe*r; const uint8_t*in; uint8_t*out; size_t off,len; fe h; } job;
static void* worker(void*a){
  job*j=(job*)a; fe h={{0,0,0}};
  size_t CH=16384; size_t p=0;
  while(p<j->len){
    size_t n=j->len-p; if(n>CH) n=CH;
    size_t off=j->off+p;
    chacha_xor(j->st,(uint32_t)(1+off/64),j->in+off,j->out+off,n);
    poly_padded(&h,j->r,j->out+off,n); /* n multiple of 16 except at end */
    p+=n;
  }
  j->h=h; return 0;
}
void cc20p(const uint8_t*key,const uint8_t*nonce,const uint8_t*aad,size_t aadlen,const uint8_t*in,size_t len,uint8_t*out,uint8_t*tag,int nth){
  uint32_t st[16]={0x61707865,0x3320646e,0x79622d32,0x6b206574};
  for(int i=0;i<8;i++) st[4+i]=ld32(key+4*i);
  st[12]=0; st[13]=ld32(nonce); st[14]=ld32(nonce+4); st[15]=ld32(nonce+8);
  uint32_t ks[16]; block1(st,ks); uint8_t*k=(uint8_t*)ks;
  uint64_t t0=ld64(k)&0x0ffffffc0fffffffULL, t1=ld64(k+8)&0x0ffffffc0ffffffcULL;
  fe r={{t0&M44,((t0>>44)|(t1<<20))&M44,(t1>>24)&M42}};
  if(nth<1) nth=1; if(nth>64) nth=64;
  size_t per=(len/nth+16383)/16384*16384; if(per==0) per=16384;
  job js[64]; pthread_t th[64]; int nj=0;
  for(size_t off=0;off<len&&nj<64;off+=per){ js[nj].st=st; js[nj].r=&r; js[nj].in=in; js[nj].out=out; js[nj].off=off; js[nj].len=(len-off<per)?len-off:per; nj++; }
  for(int i=1;i<nj;i++) pthread_create(&th[i],0,worker,&js[i]);
  if(nj) worker(&js[0]);
  fe h={{0,0,0}}; poly_padded(&h,&r,aad,aadlen);
  for(int i=1;i<nj;i++) pthread_join(th[i],0);
  fe rp; int have=0; 
  for(int i=0;i<nj;i++){
    uint64_t nb=(js[i].len+15)/16;
    if(!(have && i<nj-1 && js[i].len==per)){ fe_pow(&rp,&r,nb); have=(js[i].len==per); }
    fe_mul(&h,&h,&rp); fe_add(&h,&js[i].h);
  }
  uint8_t lb[16]; uint64_t a=aadlen,c=len; memcpy(lb,&a,8); memcpy(lb+8,&c,8);
  poly_blocks(&h,&r,lb,1);
  /* full carry & reduce */
  uint64_t h0=h.h[0],h1=h.h[1],h2=h.h[2],cc;
  cc=h1>>44;h1&=M44;h2+=cc; cc=h2>>42;h2&=M42;h0+=cc*5; cc=h0>>44;h0&=M44;h1+=cc;
  cc=h1>>44;h1&=M44;h2+=cc; cc=h2>>42;h2&=M42;h0+=cc*5; cc=h0>>44;h0&=M44;h1+=cc;
  uint64_t g0=h0+5; cc=g0>>44; g0&=M44; uint64_t g1=h1+cc; cc=g1>>44; g1&=M44; uint64_t g2=h2+cc-(1ULL<<42);
  uint64_t mask=(g2>>63)-1; /* all ones if g2 nonneg */
  h0=(h0&~mask)|(g0&mask); h1=(h1&~mask)|(g1&mask); h2=(h2&~mask)|(g2&mask);
  uint64_t s0=ld64(k+16),s1=ld64(k+24);
  uint64_t lo=h0|(h1<<44), hi=(h1>>20)|(h2<<24);
  u128 sum=(u128)lo+s0; lo=(uint64_t)sum; hi=hi+s1+(uint64_t)(sum>>64);
  memcpy(tag,&lo,8); memcpy(tag+8,&hi,8);
}
